mapper.select:
SELECT
FROM operation_activity oa LEFT JOIN city c ON c.id = oa.city_id AND c.region = oa.region LEFT JOIN ( SELECT activity_id, COUNT(1) AS item_count FROM operation_activity_item WHERE status = 1 GROUP BY activity_id ) stats ON stats.activity_id = oa.id WHERE oa.region = #{region} AND
AND (oa.city_id = 0 OR oa.city_id = #{cityId})
AND oa.channel = #{channel}
ORDER BY CASE WHEN oa.city_id = 0 THEN 1 ELSE 0 END ASC, CASE WHEN oa.start_at IS NULL THEN 1 ELSE 0 END ASC, oa.start_at DESC, oa.id DESC
LIMIT #{limit}
